// Vite config for the results site. Every page is generated by the route
// plugin in scripts/routes.mjs from pages/<type>.html and data/*.json.
// The site lives at the root of its domain (website/tools/publish.json); build and publish
// only through python website/tools/publish.py.
import { defineConfig } from 'vite';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { routePlugin } from './scripts/routes.mjs';

const root = dirname(fileURLToPath(import.meta.url));

export default defineConfig({
  root,
  base: '/',
  appType: 'mpa',
  publicDir: 'public',
  plugins: [routePlugin({ root })],
  server: { port: 5180, strictPort: false },
  preview: { port: 5181 },
  build: {
    outDir: 'dist',
    emptyOutDir: true,
    target: 'es2022',
    assetsInlineLimit: 0,
    chunkSizeWarningLimit: 900,
  },
});
